        java.util.concurrent.atomic.AtomicInteger n=new java.util.concurrent.atomic.AtomicInteger(); Thread a=new Thread(()->{for(int i=0;i<100;i++) n.incrementAndGet();}); Thread b=new Thread(()->{for(int i=0;i<100;i++) n.incrementAndGet();}); a.start(); b.start(); a.join(); b.join(); System.out.println(n.get());
